What does this print?

```dart
int simpleHash(String key) {
  var hash = 0;
  for (final u in key.codeUnits) {
    hash = (hash * 31 + u) & 0x7fffffff;
  }
  return hash;
}

void main() {
  print(simpleHash('a'));
  print(simpleHash('ab'));
}
```

